package com.contextgraph.model; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="documents",indexes={@Index(name="idx_doc_owner",columnList="owner_id"),@Index(name="idx_doc_created",columnList="createdAt")}) public class Document {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false) String originalName; @Column(nullable=false) String storedName; String contentType; Long sizeBytes; @Lob @Column(columnDefinition="TEXT") String extractedText; @Column(columnDefinition="TEXT") String keywords; @Column(columnDefinition="TEXT") String entities; @Column(columnDefinition="TEXT") String dates; String topic; String checksum; @Column(nullable=false) LocalDateTime createdAt=LocalDateTime.now(); @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="owner_id") User owner; public Long getId(){return id;} public String getOriginalName(){return originalName;} public String getStoredName(){return storedName;} public String getContentType(){return contentType;} public Long getSizeBytes(){return sizeBytes;} public String getExtractedText(){return extractedText;} public String getKeywords(){return keywords;} public String getEntities(){return entities;} public String getDates(){return dates;} public String getTopic(){return topic;} public String getChecksum(){return checksum;} public LocalDateTime getCreatedAt(){return createdAt;} public User getOwner(){return owner;} public void setOriginalName(String v){originalName=v;} public void setStoredName(String v){storedName=v;} public void setContentType(String v){contentType=v;} public void setSizeBytes(Long v){sizeBytes=v;} public void setExtractedText(String v){extractedText=v;} public void setKeywords(String v){keywords=v;} public void setEntities(String v){entities=v;} public void setDates(String v){dates=v;} public void setTopic(String v){topic=v;} public void setChecksum(String v){checksum=v;} public void setOwner(User v){owner=v;}}